using System.Collections;
using UnityEngine;
using Sheytoonak.Core.Duel;

namespace Sheytoonak
{
    /// <summary>
    /// Background music from Resources/Audio/Music (user 2026-11-06, generated by the user from the prompts in
    /// docs/ART_SPEC.fa.md): <c>duel_loop</c> from the draft to the end, <c>tension_loop</c> once either side
    /// is one window short of the majority, <c>sting_win</c>/<c>sting_lose</c> at the end, <c>lobby_loop</c>
    /// («Morning in Beirut», the second take: the first was «زیادی غمگین») on the home screen. Two sources
    /// crossfade so a switch never clicks; a missing clip simply plays nothing.
    /// </summary>
    public class MusicPlayer : MonoBehaviour
    {
        [Range(0f, 1f)] public float volume = 0.55f;
        // User (2026-11-07): «موسیقی خیلی یهویی عوض می‌شه، بهتره فید شه اول بعد اون یکی آروم شروع شه بعد صداش بیشتر بشه»:
        // the old bed fades out completely, a short breath, then the new one rises from silence.
        public float fadeOutSeconds = 1.2f, gapSeconds = 0.35f, fadeInSeconds = 2.5f;

        AudioClip duelLoop, tensionLoop, stingWin, stingLose, lobbyLoop;
        AudioSource a, b, sting;   // a/b alternate as the music bed, sting is one-shot
        AudioSource live;          // the bed currently fading in / playing
        DuelManager duel;
        bool tense;

        void Awake()
        {
            duelLoop = Resources.Load<AudioClip>("Audio/Music/duel_loop");
            tensionLoop = Resources.Load<AudioClip>("Audio/Music/tension_loop");
            stingWin = Resources.Load<AudioClip>("Audio/Music/sting_win");
            stingLose = Resources.Load<AudioClip>("Audio/Music/sting_lose");
            lobbyLoop = Resources.Load<AudioClip>("Audio/Music/lobby_loop");
            a = Bed(); b = Bed();
            sting = gameObject.AddComponent<AudioSource>();
            sting.playOnAwake = false; sting.spatialBlend = 0f;
            duel = GetComponent<DuelManager>();
        }

        AudioSource Bed()
        {
            var s = gameObject.AddComponent<AudioSource>();
            s.playOnAwake = false; s.loop = true; s.spatialBlend = 0f; s.volume = 0f;
            return s;
        }

        void OnEnable()
        {
            if (duel == null) return;
            duel.DraftStarted += OnDraft;
            duel.DuelStarted += OnDuel;
            duel.Finished += OnFinished;
        }

        void OnDisable()
        {
            if (duel == null) return;
            duel.DraftStarted -= OnDraft;
            duel.DuelStarted -= OnDuel;
            duel.Finished -= OnFinished;
        }

        void OnDraft() { tense = false; lobbyAt = -1f; Switch(duelLoop); }
        void OnDuel() { tense = false; if (live == null || live.clip != duelLoop) Switch(duelLoop); }

        void OnFinished(Side winner, bool iWon)
        {
            Switch(null);
            var c = iWon ? stingWin : stingLose;
            if (c != null) sting.PlayOneShot(c, volume);
            lobbyAt = Time.unscaledTime + (c != null ? c.length : 0f) + 0.5f; // the lobby tune waits for the sting
        }

        float lobbyAt = -1f;
        bool OnLobby => live != null && (live.clip == lobbyLoop || pendingClip == lobbyLoop);
        AudioClip pendingClip;

        void Update()
        {
            var r = duel != null ? duel.Rules : null;
            if (r == null || r.Finished)
            {
                // home screen (ToHome nulls the rules) or the result card: the lobby tune, once the sting has played
                if (lobbyLoop != null && !OnLobby && Time.unscaledTime >= lobbyAt) Switch(lobbyLoop);
                else if (lobbyLoop == null && r == null && live != null) Switch(null);
                return;
            }
            bool nearEnd = r.Windows[0] >= r.Majority - 1 || r.Windows[1] >= r.Majority - 1;
            if (nearEnd && !tense && tensionLoop != null) { tense = true; Switch(tensionLoop); }
        }

        /// <summary>Fade the bed out, then bring <paramref name="clip"/> in from silence (null = stay silent).</summary>
        void Switch(AudioClip clip)
        {
            var from = live;
            var to = clip == null ? null : (from == a ? b : a);
            live = to; pendingClip = clip;
            StopAllCoroutines();
            StartCoroutine(Fade(from, to, clip));
        }

        IEnumerator Fade(AudioSource from, AudioSource to, AudioClip clip)
        {
            float t = 0f, f0 = from != null ? from.volume : 0f;
            while (from != null && t < fadeOutSeconds)
            {
                t += Time.unscaledDeltaTime;
                from.volume = Mathf.Lerp(f0, 0f, Mathf.Clamp01(t / fadeOutSeconds));
                yield return null;
            }
            if (from != null) { from.volume = 0f; from.Stop(); }
            if (to == null) yield break;
            if (from != null) yield return new WaitForSecondsRealtime(gapSeconds);
            to.clip = clip; to.volume = 0f; to.Play();
            t = 0f;
            while (t < fadeInSeconds)
            {
                t += Time.unscaledDeltaTime;
                to.volume = Mathf.Lerp(0f, volume, Mathf.Clamp01(t / fadeInSeconds));
                yield return null;
            }
            to.volume = volume;
        }
    }
}
